sys_ux_data_broker_transform.script:
function transform(input) {

    function fetchKPIs() {
        var kpis = [];
        var propertyValue = gs.getProperty('sam.foundation.current.users.kpi');

        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue);
                gs.info("Fetched KPI Data: " + JSON.stringify(kpis));
            } catch (e) {
                gs.info("Error parsing KPI property: " + e.message);
            }
        }
        return kpis;
    }

    function getQueryCount(tableName, query) {
        try {
            var gr = new GlideAggregate(tableName);
            if (query && query !== "none") {
                gr.addEncodedQuery(query);
            }
            gr.addAggregate('COUNT');
            gr.query();

            return gr.next() ? parseInt(gr.getAggregate('COUNT'), 10) : 0;
        } catch (error) {
            gs.info("Error querying table " + tableName + ": " + error.message);
            return 0;
        }
    }

    function getTotalUsers() {
        var gr = new GlideAggregate('sys_user');
        gr.addEncodedQuery('active=true');
        gr.addAggregate('COUNT');
        gr.query();

        return gr.next() ? parseInt(gr.getAggregate('COUNT'), 10) : 0;
    }

    function calculateAverageScore() {
        gs.info("Start: Calculating Average KPI Score...");

        var kpis = fetchKPIs();
        var totalUsers = getTotalUsers();

        if (!totalUsers || !kpis.length) {
            gs.info("No valid users or KPIs found. Returning 0.");
            return 0;
        }

        var totalPercentage = 0;

        kpis.forEach(function(kpi) {
            if (kpi.table && kpi.field) {
                var count = getQueryCount(kpi.table, kpi.field);
                var percentage = (count / totalUsers) * 100;
                totalPercentage += percentage;
            }
        });

        var averagePercentage = (totalPercentage / kpis.length).toFixed(2);
        gs.info("Final Average KPI Score: " + averagePercentage);
        return parseFloat(averagePercentage); // Ensure it's a number
    }

    return calculateAverageScore(); // Returns only a number, no JSON object
}
